  responsibilityMatrix: {
    iExecute: [
      { en: "The final decision on any matter affecting the vessel's safety, navigation, or the safety of life", fr: "La décision finale sur toute question affectant la sécurité du navire, la navigation, ou la sécurité des vies" },
      { en: "Direct command of the vessel during high-risk manoeuvres or emergencies, when personal conduct is genuinely required", fr: "Le commandement direct du navire pendant les manœuvres à haut risque ou les urgences, lorsque la conduite personnelle est véritablement requise" },
      { en: "Authorization of any emergency action, exceptional deviation, or departure from standard procedure", fr: "L'autorisation de toute action d'urgence, d'écart exceptionnel, ou de dérogation à la procédure standard" },
      { en: "Communication with the company (DPA), authorities, agents, and charterers on matters of significant consequence", fr: "La communication avec la compagnie (DPA), les autorités, agents, et affréteurs sur des questions de conséquence significative" },
      { en: "The final decision to sail, remain in port, anchor, abandon ship, or seek external assistance", fr: "La décision finale d'appareiller, de rester au port, de mouiller, d'abandonner le navire, ou de rechercher une assistance externe" },
    ],
    iMonitor: [
      { en: "Consistency and integration between the Deck and Engine departments' reports, plans, and priorities", fr: "La cohérence et l'intégration entre les rapports, plans, et priorités des services Pont et Machine" },
      { en: "The vessel's overall material condition, certification, and compliance status relative to what documentation claims", fr: "L'état matériel global, la certification, et le statut de conformité du navire par rapport à ce que prétend la documentation" },
      { en: "Crew welfare, fatigue, and morale across the whole vessel, not within a single department", fr: "Le bien-être, la fatigue, et le moral de l'équipage à l'échelle de tout le navire, pas au sein d'un seul service" },
      { en: "The company's and external parties' (charterer, authority) pressure relative to the vessel's genuine safety and compliance needs", fr: "La pression de la compagnie et des parties externes (affréteur, autorité) par rapport aux besoins réels de sécurité et de conformité du navire" },
      { en: "The vessel's readiness to respond to a major emergency at all times, including during routine operations", fr: "L'état de préparation du navire à répondre à une urgence majeure à tout moment, y compris pendant les opérations routinières" },
    ],
    iReport: [
      { en: "A reconciled, whole-vessel assessment to the company (DPA), never a collection of separate departmental reports", fr: "Une évaluation réconciliée à l'échelle du navire à la compagnie (DPA), jamais une collection de rapports départementaux séparés" },
      { en: "Any reportable incident, casualty, or environmental event, accurately, promptly, and distinguishing confirmed facts from matters under investigation", fr: "Tout incident, accident, ou événement environnemental à signaler, avec précision, rapidité, et en distinguant les faits confirmés des questions en investigation" },
      { en: "Any deviation from standing instructions, the passage plan, or company procedure, together with its reasoning", fr: "Tout écart par rapport aux instructions permanentes, au plan de traversée, ou à la procédure de la compagnie, avec son raisonnement" },
      { en: "Any recurring or systemic issue across departments suggesting a need for company-level attention or resource", fr: "Tout problème récurrent ou systémique à travers les services suggérant un besoin d'attention ou de ressource au niveau de la compagnie" },
      { en: "My own uncertainty when a situation cannot be fully resolved with the information and resources available aboard", fr: "Ma propre incertitude lorsqu'une situation ne peut être entièrement résolue avec les informations et ressources disponibles à bord" },
    ],
    iDoNotAuthorize: [
      { en: "Any action that violates international law (SOLAS, MARPOL, COLREG) or flag State requirements, regardless of commercial or company pressure", fr: "Toute action qui viole le droit international (SOLAS, MARPOL, COLREG) ou les exigences de l'État du pavillon, quelle que soit la pression commerciale ou de la compagnie" },
      { en: "Falsification, omission, or alteration of any official record to misrepresent what actually occurred", fr: "La falsification, l'omission, ou l'altération de tout registre officiel pour représenter faussement ce qui s'est réellement produit" },
      { en: "Delegation of my own accountability for the vessel's overall safety and compliance, even where operational authority is properly assigned to department heads", fr: "La délégation de ma propre responsabilité pour la sécurité et la conformité globales du navire, même lorsque l'autorité opérationnelle est correctement assignée aux chefs de service" },
      { en: "Commercial or schedule pressure overriding a genuine safety, stability, or environmental concern", fr: "La pression commerciale ou de calendrier l'emportant sur une véritable préoccupation de sécurité, de stabilité, ou environnementale" },
      { en: "The use of emergency or command authority for convenience rather than genuine necessity", fr: "L'utilisation de l'autorité d'urgence ou de commandement par commodité plutôt que par nécessité réelle" },
    ],
  },

